css:
:root{--ink:#233342;--muted:#596877;--accent:#265976;--warm:#ad472d;--line:#d6dcd9;--paper:#fcfbf8;--soft:#edf2f1}
body{background:var(--paper);color:var(--ink);font-family:"Microsoft YaHei",system-ui,sans-serif;font-size:16px;line-height:1.95}
.paper-reading{max-width:1120px;margin:auto;padding:40px clamp(18px,5vw,58px) 80px;overflow-wrap:anywhere}
.paper-reading h1{font:normal clamp(32px,5vw,58px)/1.12 Georgia,"Noto Serif SC",serif;letter-spacing:-.025em;margin:18px 0 26px;text-wrap:balance}
.paper-reading h2{font-size:clamp(25px,3.5vw,34px);font-weight:500;line-height:1.4;margin:0 0 20px;text-wrap:balance}
.paper-reading h3{font-size:20px;font-weight:500;line-height:1.5}.paper-reading p{margin:12px 0 18px}
.paper-hero{padding:16px 0 38px;border-bottom:1px solid var(--line)}
.paper-hero .paper-thesis{font-size:18px;line-height:1.95;max-width:55ch}.paper-hero nav{display:flex;flex-wrap:wrap;gap:8px 22px;margin:26px 0 0}
.paper-hero nav a{font-size:13px;color:var(--accent);text-decoration:underline;text-underline-offset:6px}
.paper-chapter{padding:48px 0 34px;border-bottom:1px solid var(--line);min-width:0}
.paper-chapter :where(section,article,div,figure,fieldset){min-width:0}
.paper-chapter :where(table){display:block;max-width:100%;overflow:auto}
.paper-chapter :where(pre){white-space:pre-wrap;overflow-wrap:anywhere}
.paper-reading button{border:1px solid var(--line);background:transparent;color:var(--accent);padding:8px 14px;min-height:38px;border-radius:4px;font-size:13px;line-height:1.5}
.paper-reading button:hover{background:var(--soft)}.paper-reading button:disabled{opacity:.5;cursor:default}
.paper-reading input[type=range]{accent-color:var(--accent);max-width:100%;min-width:0}.paper-reading input[type=number]{width:90px}
.paper-reading select,.paper-reading input[type=number]{padding:7px 9px;border:1px solid var(--line);background:var(--paper);color:var(--ink);font-size:14px;border-radius:4px;max-width:100%}
.paper-reading input[type=checkbox]{accent-color:var(--warm)}.paper-reading label{font-size:14px;line-height:1.7}
.paper-reading svg,.paper-reading canvas{display:block;max-width:100%;height:auto}
.paper-reading details{padding:14px 0;border-top:1px solid var(--line);margin-top:20px}.paper-reading summary{cursor:pointer;color:var(--accent);font-size:14px}
.paper-reading table{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}
.paper-reading th,.paper-reading td{padding:9px 7px;text-align:left;border-bottom:1px solid var(--line)}
.paper-reading button[data-source]{font-size:12px;color:var(--accent);border:0;padding:6px 0;margin-right:16px;text-decoration:underline;text-underline-offset:4px}
.paper-reading ::selection{background:#f3d5ac;color:#233342}.paper-reading :focus-visible{outline:2px solid var(--accent);outline-offset:4px}
.paper-reading .reading-limitations{font-size:14px;color:var(--muted);padding-top:28px}.paper-reading .reading-limitations h2{font-size:24px}
@media(max-width:480px){.paper-reading{padding-top:24px}.paper-chapter{padding-top:32px}.paper-hero .paper-thesis{font-size:16px}.paper-reading{font-size:15px}.paper-reading h2{font-size:25px}.paper-reading table{font-size:12px}}

@scope (#chapter-ch1_arch_flow){.pm-chapter-container {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink, #1a1a1a);
  background-color: var(--paper, #ffffff);
  line-height: 1.6;
  padding: 20px;
  max-width: 900px;
  margin: 0 auto;
  box-sizing: border-box;
}

.pm-chapter-container * {
  box-sizing: border-box;
}

.pm-section {
  margin-bottom: 40px;
  border-left: 4px solid var(--line, #e0e0e0);
  padding-left: 20px;
}

.pm-section-title {
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 16px;
  color: var(--ink, #1a1a1a);
}

.pm-text {
  font-size: 16px;
  margin-bottom: 16px;
  color: var(--ink, #1a1a1a);
}

.pm-small {
  font-size: 14px;
  color: var(--muted, #666666);
}

.pm-diagram-wrapper {
  background: var(--paper, #ffffff);
  border: 1px solid var(--line, #e0e0e0);
  padding: 20px;
  margin: 20px 0;
  border-radius: 4px;
  overflow-x: auto;
}

.pm-arch-svg {
  width: 100%;
  height: auto;
  min-width: 320px;
  display: block;
}

.pm-block {
  stroke: var(--ink, #1a1a1a);
  stroke-width: 1.5;
  fill: var(--paper, #ffffff);
  transition: fill 0.3s ease;
}

.pm-block-input { fill: #f0f4f8; }
.pm-block-pos { fill: #e3f2fd; }
.pm-block-encoder { fill: #e0f7fa; }
.pm-block-decoder { fill: #fff3e0; }
.pm-block-output { fill: #f3e5f5; }

.pm-label {
  font-size: 12px;
  fill: var(--ink, #1a1a1a);
  font-family: monospace;
}

.pm-label-sub {
  font-size: 10px;
  fill: var(--muted, #666666);
  font-family: monospace;
}

.pm-connector {
  stroke: var(--line, #cccccc);
  stroke-width: 2;
  fill: none;
  marker-end: url(#ch1_arch_flow--arrow-head);
}

.pm-flow-path {
  transition: opacity 0.3s ease;
}

.pm-controls {
  margin-top: 15px;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.pm-btn {
  font-size: 14px;
  padding: 8px 16px;
  background: var(--paper, #ffffff);
  border: 1px solid var(--line, #cccccc);
  color: var(--ink, #1a1a1a);
  cursor: pointer;
  border-radius: 4px;
  transition: background 0.2s;
}

.pm-btn:hover {
  background: var(--line, #f0f0f0);
}

.pm-btn-source {
  border-color: var(--muted, #999999);
  color: var(--muted, #666666);
}

.pm-btn-concept {
  border-color: var(--accent, #007bff);
  color: var(--accent, #007bff);
}

.pm-stepper-container {
  border: 1px solid var(--line, #e0e0e0);
  padding: 20px;
  margin: 20px 0;
  border-radius: 4px;
}

.pm-stepper-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 15px;
}

.pm-step-label {
  font-size: 14px;
  color: var(--muted, #666666);
}

.pm-step-content {
  min-height: 80px;
  margin-bottom: 15px;
}

.pm-step-title {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--ink, #1a1a1a);
}

.pm-step-text {
  font-size: 15px;
  color: var(--ink, #1a1a1a);
}

.pm-stepper-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  border-top: 1px solid var(--line, #e0e0e0);
  padding-top: 15px;
}

.pm-note-block {
  background: #f9f9f9;
  border-left: 3px solid var(--accent, #007bff);
  padding: 15px;
  margin-top: 20px;
}

@media (prefers-reduced-motion: reduce) {
  .pm-flow-path, .pm-block {
    transition: none;
  }
}

@media (max-width: 480px) {
  .pm-text { font-size: 15px; }
  .pm-btn { font-size: 13px; padding: 6px 12px; }
}
button[data-source]{background:#fff!important;color:#265976!important}
.katex{display:inline-block;max-width:100%;overflow-x:auto;vertical-align:middle}.step-controls,.control-buttons{flex-wrap:wrap} @media(max-width:480px){.metric-card,.stat-card{min-width:0}}
.diagram-readable-scroll{max-width:100%;overflow-x:auto}.pm-arch-svg{width:800px!important;min-width:800px;max-width:none!important}.pm-label{font-size:16px}.pm-label-sub{font-size:14px}.diagram-scroll-hint{font-size:14px;color:var(--muted)}}
@scope (#chapter-ch2_encoder_unit){:root {
  --ink: #1a1a1a;
  --muted: #666666;
  --accent: #0066cc;
  --warm: #e6f0ff;
  --line: #e0e0e0;
  --paper: #ffffff;
  --code-bg: #f5f5f5;
  --highlight: #fff4e5;
}

.chapter-container {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.6;
  padding: 20px;
  max-width: 800px;
  margin: 0 auto;
  box-sizing: border-box;
}

.chapter-header {
  border-bottom: 2px solid var(--ink);
  margin-bottom: 30px;
  padding-bottom: 10px;
}

.chapter-title {
  font-size: 24px;
  font-weight: 700;
  margin: 0 0 10px 0;
  color: var(--ink);
}

.chapter-takeaway {
  font-size: 16px;
  color: var(--muted);
  margin: 0;
  font-style: italic;
}

.node-block {
  margin-bottom: 40px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 20px;
  background: #fff;
}

.node-title {
  font-size: 20px;
  font-weight: 600;
  margin-top: 0;
  margin-bottom: 15px;
  color: var(--accent);
  border-left: 4px solid var(--accent);
  padding-left: 10px;
}

.node-summary {
  font-size: 15px;
  margin-bottom: 20px;
  color: var(--ink);
}

/* Stepper Styles */
.interactive-stepper {
  background: var(--warm);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 20px;
  margin: 20px 0;
}

.stepper-controls {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 15px;
  margin-bottom: 20px;
}

.control-btn {
  background: var(--paper);
  border: 1px solid var(--accent);
  color: var(--accent);
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  transition: all 0.2s;
}

.control-btn:hover {
  background: var(--accent);
  color: var(--paper);
}

.control-btn.secondary {
  border-color: var(--muted);
  color: var(--muted);
}

.control-btn.secondary:hover {
  background: var(--muted);
  color: var(--paper);
}

.step-label {
  font-weight: 600;
  font-size: 14px;
  color: var(--ink);
  min-width: 80px;
  text-align: center;
}

.stepper-visual {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.flow-diagram {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: 100%;
  max-width: 300px;
}

.flow-node {
  background: var(--paper);
  border: 2px solid var(--line);
  border-radius: 6px;
  padding: 10px;
  width: 100%;
  text-align: center;
  transition: all 0.3s ease;
  opacity: 0.6;
  transform: scale(0.98);
}

.flow-node.active {
  border-color: var(--accent);
  background: #fff;
  opacity: 1;
  transform: scale(1.02);
  box-shadow: 0 4px 12px rgba(0, 102, 204, 0.15);
  z-index: 2;
}

.flow-node input-node,
.flow-node output-node {
  background: var(--code-bg);
  border-style: dashed;
  opacity: 1;
  transform: scale(1);
}

.flow-arrow {
  color: var(--muted);
  font-size: 18px;
  font-weight: bold;
  opacity: 0.5;
  transition: opacity 0.3s;
}

.flow-arrow.active {
  opacity: 1;
  color: var(--accent);
}

.label {
  display: block;
  font-weight: 600;
  font-size: 14px;
  margin-bottom: 4px;
}

.detail {
  display: block;
  font-size: 12px;
  color: var(--muted);
  font-family: monospace;
}

.formula-preview {
  display: block;
  font-family: "Times New Roman", Times, serif;
  font-style: italic;
  font-size: 14px;
  color: var(--ink);
  background: var(--code-bg);
  padding: 2px 6px;
  border-radius: 4px;
  margin-top: 4px;
}

.dimension-tag {
  display: inline-block;
  font-size: 11px;
  background: var(--ink);
  color: var(--paper);
  padding: 2px 6px;
  border-radius: 10px;
  margin-top: 6px;
  font-family: monospace;
}

.stepper-explanation {
  margin-top: 25px;
  padding: 15px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 6px;
  width: 100%;
  box-sizing: border-box;
}

.stepper-explanation h3 {
  margin: 0 0 10px 0;
  font-size: 16px;
  color: var(--accent);
}

.stepper-explanation p {
  margin: 0;
  font-size: 14px;
  color: var(--ink);
}

/* Formula Card */
.formula-card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 20px;
  margin: 20px 0;
}

.formula-display {
  font-family: "Times New Roman", Times, serif;
  font-size: 20px;
  text-align: center;
  padding: 15px;
  background: var(--code-bg);
  border-radius: 4px;
  margin-bottom: 20px;
  color: var(--ink);
}

.formula-conditions h4 {
  font-size: 15px;
  margin: 0 0 10px 0;
  color: var(--ink);
}

.condition-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.condition-list li {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
  font-size: 14px;
}

.condition-list li:last-child {
  border-bottom: none;
}

.condition-label {
  color: var(--muted);
  font-weight: 500;
}

.condition-value {
  color: var(--ink);
  font-family: monospace;
  font-weight: 600;
}

/* Teaching Note */
.teaching-note {
  background: #fff8e1;
  border-left: 4px solid #ffc107;
  padding: 15px;
  margin: 20px 0;
  font-size: 14px;
  color: #5d4037;
}

.teaching-note h4 {
  margin: 0 0 10px 0;
  font-size: 15px;
}

.teaching-note ul {
  margin: 0;
  padding-left: 20px;
}

.teaching-note li {
  margin-bottom: 5px;
}

/* Source Button */
.source-block {
  margin-top: 20px;
  text-align: right;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 6px 12px;
  font-size: 12px;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--ink);
  color: var(--ink);
  background: var(--code-bg);
}

/* Responsive */
@media (max-width: 480px) {
  .chapter-container {
    padding: 10px;
  }

  .node-block {
    padding: 15px;
  }

  .formula-display {
    font-size: 16px;
    overflow-x: auto;
  }

  .condition-list li {
    flex-direction: column;
    gap: 4px;
  }
}
button[data-source]{background:#fff!important;color:#265976!important}
.katex{display:inline-block;max-width:100%;overflow-x:auto;vertical-align:middle}.step-controls,.control-buttons{flex-wrap:wrap} @media(max-width:480px){.metric-card,.stat-card{min-width:0}}}
@scope (#chapter-ch3_decoder_mask){#ch3_decoder_mask--ch3_decoder_mask {
  --warm-accent: #d97706;
  --warm-light: #fef3c7;
  --cold-accent: #2563eb;
  --mask-color: #e5e7eb;
  --mask-pattern: repeating-linear-gradient(45deg, #e5e7eb, #e5e7eb 10px, #f3f4f6 10px, #f3f4f6 20px);

  font-family: inherit;
