@scope (#chapter-ch4_attention_core){:root {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #2563eb;
  --warm: #d97706;
  --line: #e5e5e5;
  --paper: #ffffff;
  --q-color: #2563eb;
  --k-color: #059669;
  --v-color: #d97706;
}

.pm-chapter {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 24px;
  line-height: 1.6;
  font-size: 16px;
  max-width: 1200px;
  margin: 0 auto;
  box-sizing: border-box;
}

.pm-chapter * {
  box-sizing: border-box;
}

.pm-header {
  border-bottom: 2px solid var(--line);
  padding-bottom: 16px;
  margin-bottom: 24px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 16px;
}

.pm-title {
  font-size: 24px;
  font-weight: 700;
  margin: 0;
  color: var(--ink);
}

.pm-meta {
  display: flex;
  gap: 12px;
  align-items: center;
}

.pm-btn-source {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 6px 12px;
  font-size: 14px;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
}

.pm-btn-source:hover {
  border-color: var(--ink);
  color: var(--ink);
}

.pm-concept-tag {
  font-size: 13px;
  background: #f3f4f6;
  padding: 4px 8px;
  border-radius: 4px;
  color: var(--muted);
  border: 1px solid var(--line);
}

.pm-content-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .pm-content-grid {
    grid-template-columns: 350px 1fr;
  }
}

.pm-panel {
  background: #fafafa;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 20px;
}

.pm-text {
  font-size: 15px;
  color: var(--ink);
  margin-bottom: 16px;
}

.pm-alert {
  background: #eff6ff;
  border-left: 4px solid var(--accent);
  padding: 12px;
  font-size: 14px;
  color: #1e40af;
}

.pm-viz-container {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

@media (min-width: 900px) {
  .pm-viz-container {
    flex-direction: row;
    align-items: stretch;
  }
}

.pm-viz-column {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.pm-viz-label {
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  margin-bottom: 8px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 4px;
}

.pm-vector-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pm-vector-item {
  background: #fff;
  border: 1px solid var(--line);
  padding: 12px;
  border-radius: 6px;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  font-size: 14px;
}

.pm-vector-item.pm-q { border-color: var(--q-color); }
.pm-vector-item.pm-k { border-color: var(--k-color); }
.pm-vector-item.pm-v { border-color: var(--v-color); }

.pm-label {
  display: block;
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 6px;
  font-weight: 600;
}

.pm-controls label {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  margin-bottom: 4px;
  color: var(--ink);
}

.pm-controls input[type="range"] {
  width: 100px;
  margin-left: 8px;
}

.pm-vector-display {
  margin-top: 8px;
  font-weight: 700;
  color: var(--ink);
}

.pm-process {
  background: #fff;
  border: 1px solid var(--line);
  padding: 16px;
  border-radius: 6px;
}

.pm-calc-block {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.pm-calc-row {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pm-calc-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--muted);
}

.pm-bar-container {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pm-bar-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-family: monospace;
}

.pm-bar-label {
  width: 40px;
  text-align: right;
  color: var(--muted);
}

.pm-bar-bg {
  flex: 1;
  height: 8px;
  background: #f3f4f6;
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}

.pm-bar-fill {
  height: 100%;
  width: 0%;
  transition: width 0.3s ease;
}

.pm-score-1 { background: var(--q-color); }
.pm-score-2 { background: var(--k-color); }
.pm-weight-1 { background: var(--warm); }
.pm-weight-2 { background: #a855f7; }

.pm-bar-val {
  width: 40px;
  text-align: left;
}

.pm-note {
  font-size: 11px;
  color: var(--muted);
  text-align: right;
  font-style: italic;
}

.pm-output-box {
  background: #fff;
  border: 2px solid var(--ink);
  padding: 16px;
  border-radius: 6px;
  text-align: center;
}

.pm-formula {
  font-family: monospace;
  font-size: 14px;
  margin-bottom: 12px;
  color: var(--muted);
}

.pm-output {
  font-size: 18px;
  color: var(--ink);
  margin-bottom: 16px;
}

.pm-contributors {
  display: flex;
  flex-direction: column;
  gap: 8px;
  text-align: left;
}

.pm-contributor {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}

.pm-c-label {
  width: 70px;
  color: var(--muted);
}

.pm-c-bar-bg {
  flex: 1;
  height: 6px;
  background: #f3f4f6;
  border-radius: 3px;
}

.pm-c-bar-fill {
  height: 100%;
  width: 0%;
  transition: width 0.3s ease;
}

#ch4_attention_core--contrib-1 { background: var(--warm); }
#ch4_attention_core--contrib-2 { background: #a855f7; }

.pm-teaching-note {
  margin-top: 16px;
  font-size: 12px;
  color: var(--muted);
  border-top: 1px dashed var(--line);
  padding-top: 8px;
}

.pm-footer {
  margin-top: 32px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 14px;
}

.pm-status {
  color: var(--k-color);
  font-weight: 600;
}

@media (prefers-reduced-motion: reduce) {
  .pm-bar-fill, .pm-c-bar-fill {
    transition: none;
  }
}
